(ns diplomat.markdown
  "GENERATED by jolt-diplomat-backend from the real Diplomat HIR.
  Do not hand-edit — see findings/milestone-5-findings.md."
  (:require [jolt.ffi :as ffi]
            [diplomat.runtime :as dr]
  ))

(dr/defopaque Markdown "md_Markdown_destroy_mv1")

(ffi/defcfn ^:private c-create "md_Markdown_create_mv1" [] :pointer)
(defn create [] (->Markdown (c-create ) false))

(ffi/defcfn ^:private c-to-html "jolt_md_Markdown_to_html_mv1" [:string :size_t :pointer] :void)
(defn to-html [input]
  (let [buf (ffi/alloc 256) w (ffi/alloc dr/writeable-struct-size)]
    (try
      (dr/simple-write! buf 256 w)
      (c-to-html input (count input) w)
      (let [n (ffi/read w :size_t dr/O-len)] (ffi/read-bytes buf n))
      (finally (ffi/free buf) (ffi/free w))))
)

